#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // We'll place elements 1,2,...,n into positions 0,1,...,n-1
    // When placing element (i+1) into position i, we work with subarray p[i..n-1]
    // We need to bring p[i..n-1]'s target to front of this subarray
    // But operations work on the WHOLE array. So we simulate on whole array.

    // Strategy: to place value (i+1) at position i:
    // Find position j where p[j] = i+1 (j >= i since earlier positions are fixed... not necessarily with whole-array ops)

    // Since operations act on the whole array, we can't just fix a prefix.
    // Instead: use operations to sort the array. 
    // A known approach: we can achieve any permutation reachable by 3-element rotations.
    // Actually with this operation we can sort: bring smallest to front repeatedly.

    for(int i=0; i<n-1 && (int)ops.size() < 4*n; i++){
        int j = find(p.begin(), p.end(), i+1) - p.begin();
        if(j == i) continue;
        if(j == n-1){
            // Use one op: x=i+1 (prefix includes fixed part), but we need to be careful
            // swap prefix of length (i) and suffix of length 1... but need middle >=1
            // x=j, y=1: [0..j-1 | (none) | j] — need middle>=1, so x+y<n => j+1<n => j<n-1. But j=n-1, fail.
            // First move it: x=1,y=1 swaps first and last
            if(n>=3){ops.push_back({1,1}); int t=p[0];p[0]=p[n-1];p[n-1]=t; j=find(p.begin(),p.end(),i+1)-p.begin();}
        }
        if(j==i) continue;
        // op1: x=j, y=n-j => but x+y=n, need <n. So x=j, y=n-1-j if that works
        // Move p[j] to front: x=j, y=n-j, nope. Use two ops.
        if(j>0 && j<n-1){ops.push_back({j,n-1-j});vector<int>np(p.begin()+n-(n-1-j),p.end());np.insert(np.end(),p.begin()+j,p.begin()+n-(n-1-j));np.insert(np.end(),p.begin(),p.begin()+j);p=np;j=find(p.begin(),p.end(),i+1)-p.begin();}
        if(j==0&&i==0) continue;
        if(j==0&&i>0){ops.push_back({i,n-i-1});vector<int>np(p.begin()+n-(n-i-1),p.end());np.insert(np.end(),p.begin()+i,p.begin()+n-(n-i-1));np.insert(np.end(),p.begin(),p.begin()+i);p=np;}
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
